#pragma once
static void checkElectronSpacing(App& app,const std::string& dir){
 auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(std::string("electron spacing: ")+why);};auto& s=app.s;
 auto reset=[&](){s.cancel();s.doc=Document();s.doc.setDefaultTextSize(10);s.doc.documentExtensions().set("studio.style.LabelSize","10");s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.refresh();};
 reset();ObjectId o,left,right,b;s.doc.addAtom(Vec2(100,100),8,&o);s.doc.addAtom(Vec2(75,115),6,&left);s.doc.addAtom(Vec2(125,115),6,&right);s.doc.addBond(o,left,&b);s.doc.addBond(o,right,&b);auto sem=s.doc.atoms().alive(o)->semantics;sem.implicitHydrogens=0;s.doc.setAtomSemantics(o,sem);s.doc.extensions(ObjectRef(ObjectKind::Atom,o)).set("pst.attr.MoleculeStudioLonePairs","1");s.refresh();integration::RingGeometry rings(s.doc);auto labels=integration::molecular::labels(s.doc,s.glyphs,rings);auto layout=labels.at(o).layout;auto center=mechanism::lonePairGlyphCenter(s.doc,*s.doc.atoms().alive(o),&layout);auto point=mechanism::lonePairPosition(s.doc,o,0,&layout);require(std::abs(length(point-center)-7)<1e-6,"automatic lone pair closer to O");mechanism::setLonePairOffset(s.doc,o,0,Vec2(.9,-.9));auto manual=mechanism::lonePairPosition(s.doc,o,0,&layout);require(length(manual-(s.doc.atoms().alive(o)->position+Vec2(9,-9)))<1e-6,"manual lone pair position retained");
 reset();ObjectId c;s.doc.addAtom(Vec2(100,100),6,&c);for(double angle:{150.,210.}){ObjectId n;s.doc.addAtom(Vec2(100,100)+direction(angle)*25,6,&n);s.doc.addBond(c,n,&b);}sem=s.doc.atoms().alive(c)->semantics;sem.implicitHydrogens=0;sem.radical=uint8_t(Radical::Singlet);s.doc.setAtomSemantics(c,sem);s.refresh();auto dots=arrows::mechanismRadicalPoints(s.doc,c);require(dots.size()==2&&std::abs(length((dots[0]+dots[1])*.5-Vec2(100,100))-6.4)<1e-6,"carbene pair closer without changing count");s.doc.extensions(ObjectRef(ObjectKind::Atom,c)).set("pst.attr.MoleculeStudioRadicalPosition",".9 -.8");s.refresh();dots=arrows::mechanismRadicalPositions(s.doc,*s.doc.atoms().alive(c),10,nullptr);require(length((dots[0]+dots[1])*.5-Vec2(109,92))<1e-6,"manual carbene position retained");
 reset();s.doc.addAtom(Vec2(100,100),6,&c);sem=s.doc.atoms().alive(c)->semantics;sem.charge=1;sem.implicitHydrogens=0;s.doc.setAtomSemantics(c,sem);s.doc.extensions(ObjectRef(ObjectKind::Atom,c)).set("pst.attr.MoleculeStudioChargePosition","auto");auto cp=arrows::chargeMarkerCenter(s.doc,*s.doc.atoms().alive(c),10,nullptr);require(length(cp-Vec2(100,100))<7,"automatic charge closer");s.doc.extensions(ObjectRef(ObjectKind::Atom,c)).set("pst.attr.MoleculeStudioChargePosition",".9 -.9");require(length(arrows::chargeMarkerCenter(s.doc,*s.doc.atoms().alive(c),10,nullptr)-Vec2(109,91))<1e-6,"manual charge position retained");
 reset();ObjectId n;s.doc.addAtom(Vec2(100,100),6,&n);require(nicknames::apply(s.doc,n,"N3-").ok(),"azide fixture");auto plan=functional_groups::prepareExpansion(s.doc,n);std::vector<ObjectRef> made;functional_groups::applyExpansion(s.doc,plan,made);for(const auto& a:s.doc.atoms().records())if(a.isAlive()){auto p=arrows::chargeMarkerCenter(s.doc,a,10,nullptr);require(std::abs(length(p-a.position)-8)<1e-5,"automatic azide charges closer");}s.refresh();s.selected.clear();s.fit();app.invalidate();s.save(dir+"/closer-azide.cdxml",true);app.screenshot(dir+"/closer-azide.png");
 for(const auto& a:s.doc.atoms().records())if(a.isAlive()){auto& bag=s.doc.extensions(ObjectRef(ObjectKind::Atom,a.id));bag.set("pst.attr.MoleculeStudioChargePosition",a.semantics.charge<0?"0 -1.05":"0 1.05");}auto original=s.doc.digest();for(const auto& a:s.doc.atoms().records())if(a.isAlive())require(std::abs(length(arrows::chargeMarkerCenter(s.doc,a,10,nullptr)-a.position)-8)<1e-6,"legacy generated azide preset displays closer");require(original==s.doc.digest(),"legacy correction leaves document unchanged");
 reset();std::ofstream(dir+"/electron-spacing-checks.json")<<"{\"automatic_lone_pair\":true,\"automatic_charge\":true,\"automatic_carbene\":true,\"azide_charge_distance\":true,\"legacy_azide_preset\":true,\"manual_positions_retained\":true}";
}
